/** Offline integration checks for MZJ organic TikTok scheduling: no live API calls. */
import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import { createRequire } from 'node:module';
const require = createRequire(import.meta.url);
const ts = require('/opt/nvm/versions/node/v22.16.0/lib/node_modules/typescript/lib/typescript.js');
const source = fs.readFileSync(path.resolve('server/_marketing-bulkpublish.ts'), 'utf8');
const output = ts.transpileModule(source, { fileName: 'server/_marketing-bulkpublish.ts', compilerOptions: { target: ts.ScriptTarget.ES2022, module: ts.ModuleKind.ESNext, lib: ['es2022', 'dom'] }, reportDiagnostics: true });
assert.equal((output.diagnostics || []).filter(d => d.category === ts.DiagnosticCategory.Error).length, 0, 'Adapter must be syntactically valid');
const m = await import(`data:text/javascript;base64,${Buffer.from(output.outputText).toString('base64')}`);
const originalFetch = globalThis.fetch;
const originalKey = process.env.BULKPUBLISH_API_KEY;
const originalChannel = process.env.BULKPUBLISH_TIKTOK_CHANNEL_ID;
const date = '2026-10-25';
const time = '20:00';
const video = Buffer.from([0, 0, 0, 24, 102, 116, 121, 112, 105, 115, 111, 109, 0, 0, 0, 0]);
const photo = Buffer.from([255, 216, 255, 224, 0, 16]);
const actions = [];
const url = 'https://internal.mzj.test/approved';
let nextMediaId = 12047;
let nextPostId = 10076;
const response = (value, code=200) => new Response(JSON.stringify(value), {status:code, headers:{'content-type':'application/json'}});
try {
  process.env.BULKPUBLISH_API_KEY = 'bp_TEST_ONLY_NOT_REAL';
  process.env.BULKPUBLISH_TIKTOK_CHANNEL_ID = '2042';
  globalThis.fetch = async (uri, options = {}) => {
    const urlValue = String(uri);
    actions.push({ url: urlValue, method: options.method || 'GET', body: options.body });
    if (urlValue === `${url}/final.mp4`) return new Response(video, {status:200, headers:{'content-type':'video/mp4'}});
    if (urlValue === `${url}/cover.jpg`) return new Response(photo, {status:200, headers:{'content-type':'image/jpeg'}});
    if (urlValue.endsWith('/api/channels')) return response({ channels:[{id:2042,platform:'tiktok',isActive:true,needsReconnect:false,capabilities:{canPublishPosts:true}}] });
    if (urlValue.endsWith('/api/media') && options.method === 'POST') return response({id:nextMediaId++});
    if (urlValue.endsWith('/api/posts') && options.method === 'POST') return response({post:{id:nextPostId++,status:'scheduled'}});
    if (/\/api\/posts\/\d+$/.test(urlValue) && options.method === 'GET') return response({post:{id:10076,status:'scheduled',postPlatforms:[{platform:'tiktok',status:'pending'}]}});
    if (/\/api\/posts\/\d+$/.test(urlValue) && options.method === 'PUT') return response({post:{id:10076,status:'scheduled'}});
    throw new Error(`Unexpected mock request: ${options.method || 'GET'} ${urlValue}`);
  };
  assert.equal(m.riyadhPublishIso(date, time), '2026-10-25T17:00:00.000Z');
  assert.throws(() => m.riyadhPublishIso('2026-02-30', '20:00'), /غير صالح/);
  assert.throws(() => m.riyadhPublishIso('2026-10-25', '29:00'), /صحيحين/);
  assert.throws(() => m.riyadhPublishIso('2025-10-25', '20:00'), /دقيقتين/);
  const videoResult = await m.scheduleBulkPublishTikTok({date,time,caption:'سوناتا 2026',hashtags:'#MZJ',files:[{fileName:'sonata.mp4',mimeType:'video/mp4',fileUrl:`${url}/final.mp4`}]});
  assert.equal(videoResult.status, 'scheduled');
  assert.equal(videoResult.postId, 10076);
  assert.equal(videoResult.mediaId, 12047);
  assert.equal(videoResult.kind, 'video');
  const videoCreate = actions.find(a => a.url.endsWith('/api/posts') && a.method === 'POST');
  const videoBody = JSON.parse(videoCreate.body);
  assert.equal(videoBody.status, 'scheduled');
  assert.equal(videoBody.scheduledAt, '2026-10-25T17:00:00.000Z');
  assert.equal(videoBody.timezone, 'Asia/Riyadh');
  assert.deepEqual(videoBody.channels,[{channelId:2042,platform:'tiktok'}]);
  assert.deepEqual(videoBody.mediaFiles,[12047]);
  assert.equal(videoBody.content,'سوناتا 2026\n\n#MZJ');
  assert.equal(videoBody.postTypeOverrides.tiktok,'video');
  assert(!actions.some(a => a.url.endsWith('/publish')),'Never use immediate publication endpoint');
  const status = await m.bulkPublishTikTokStatus(10076);
  assert.equal(status.status,'scheduled');
  const updated = await m.rescheduleBulkPublishTikTok({postId:10076,channelId:2042,mediaIds:[12047],date:'2026-10-26',time:'21:15',caption:'سوناتا 2026\n\n#MZJ'});
  assert.equal(updated.postId,10076);
  assert.equal(updated.scheduledAt,'2026-10-26T18:15:00.000Z');
  const put = actions.find(a => /\/api\/posts\/10076$/.test(a.url) && a.method==='PUT');
  const putBody=JSON.parse(put.body);
  assert.equal(putBody.status,'scheduled');
  assert.deepEqual(putBody.mediaFiles,[12047]);
  assert.equal(actions.filter(a => a.url.endsWith('/api/posts') && a.method==='POST').length,1,'No duplicate post on reschedule');
  const second = await m.scheduleBulkPublishTikTok({date,time,caption:'صور الكونا',hashtags:'#MZJ',files:[{fileName:'kona.jpg',mimeType:'image/jpeg',fileUrl:`${url}/cover.jpg`}]});
  assert.equal(second.kind,'photo_slideshow');
  const photoCreate=actions.filter(a=>a.url.endsWith('/api/posts')&&a.method==='POST').at(-1);
  assert.equal(JSON.parse(photoCreate.body).postTypeOverrides.tiktok,'photo_slideshow');
  const actionCount=actions.length;
  await assert.rejects(()=>m.scheduleBulkPublishTikTok({date,time,caption:'x',hashtags:'#MZJ',files:[{fileName:'wrong.pdf',mimeType:'application/pdf',fileUrl:`${url}/cover.jpg`}]}),/TikTok/);
  await assert.rejects(()=>m.scheduleBulkPublishTikTok({date,time,caption:'x',hashtags:'#MZJ',files:[{fileName:'wrong.mp4',mimeType:'video/mp4',fileUrl:'http://insecure.example/test.mp4'}]}),/HTTPS/);
  assert.equal(actions.filter(a=>a.url.endsWith('/api/posts')&&a.method==='POST').length,2,'Invalid inputs cannot create extra scheduled posts');
  assert.equal(actions.filter(a=>a.url.endsWith('/publish')).length,0,'No immediate publish API request');
  console.log('PASS: Offline TikTok BulkPublish video scheduling, Saudi timezone, image slideshow, status, in-place reschedule, format validation, no duplicate, and never immediate publish');
} finally {
  globalThis.fetch = originalFetch;
  if (originalKey === undefined) delete process.env.BULKPUBLISH_API_KEY; else process.env.BULKPUBLISH_API_KEY=originalKey;
  if (originalChannel === undefined) delete process.env.BULKPUBLISH_TIKTOK_CHANNEL_ID; else process.env.BULKPUBLISH_TIKTOK_CHANNEL_ID=originalChannel;
}
